-- data_ram.vhd : 256 x 8-bit data RAM storage for MiniCPU-8
-- Only 0x00..0xEF is architecturally visible RAM; cpu_top routes 0xF0..0xFF
-- to mmio instead of this block. The full array remains for debug/tests.
-- Asynchronous read, synchronous write, active-high write enable.
-- INIT is a generic (generated by tools/assembler.py from .data directives):
-- entry i is the byte at address i; addresses not covered are zero.
-- Address arithmetic and wrap-around are done by the CPU, not here.
library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;
use work.minicpu_pkg.all;

entity data_ram is
  generic (
    INIT  : ram_init_t;
    DEBUG : boolean := true);
  port (
    clk   : in  std_logic;
    we    : in  std_logic;
    addr  : in  byte_t;
    wdata : in  byte_t;
    rdata : out byte_t;
    dbg   : out ram_t);
end entity data_ram;

architecture rtl of data_ram is
  function build return ram_t is
    variable m : ram_t := (others => (others => '0'));
  begin
    for i in INIT'range loop
      if i <= 255 then
        m(i) := INIT(i);
      end if;
    end loop;
    return m;
  end function;

  signal mem : ram_t := build;
begin
  write_p : process (clk) is
  begin
    if rising_edge(clk) then
      if we = '1' then
        mem(to_integer(unsigned(addr))) <= wdata;
      end if;
    end if;
  end process;

  -- Asynchronous read; is_x guard avoids a metavalue warning in the first
  -- delta cycle, before the address has settled.
  read_p : process (all) is
  begin
    rdata <= (others => '0');
    if not is_x(addr) then
      rdata <= mem(to_integer(unsigned(addr)));
    end if;
  end process;

  -- The full debug view is useful in simulation but prevents RAM inference in
  -- GHDL/Yosys (it forces every cell to be individually readable). Board
  -- synthesis instantiates with DEBUG=false; testbenches keep the default.
  dbg_gen : if DEBUG generate
    dbg <= mem;
  else generate
    dbg <= (others => (others => '0'));
  end generate;
end architecture rtl;
